package com.roughpath.alpha;
import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.os.*;import org.java_websocket.client.WebSocketClient;import org.java_websocket.handshake.ServerHandshake;import org.json.*;import java.net.*;import java.io.*;import java.util.concurrent.*;
public class PriceMonitorService extends Service {
 private volatile WebSocketClient socket;private final ScheduledExecutorService jobs=Executors.newScheduledThreadPool(2);private PowerManager.WakeLock wake;private volatile boolean stopped=false;private volatile long lastFrame=0,lastConnect=0;private volatile boolean historyBusy=false;
 public void onCreate(){super.onCreate();MarketStore.init(this);NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("prices","Background market monitoring",NotificationManager.IMPORTANCE_LOW));Intent launch=new Intent(this,MainActivity.class);PendingIntent open=PendingIntent.getActivity(this,0,launch,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Intent stop=new Intent(this,PriceMonitorService.class).setAction("STOP");PendingIntent stopAction=PendingIntent.getService(this,1,stop,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification n=new Notification.Builder(this,"prices").setContentTitle("RoughPath is monitoring markets").setContentText("Candles and paper positions continue in the background").setSmallIcon(android.R.drawable.ic_menu_recent_history).setContentIntent(open).setOngoing(true).addAction(new Notification.Action.Builder(null,"Stop monitoring",stopAction).build()).build();try{if(Build.VERSION.SDK_INT>=34)startForeground(42,n,ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE);else startForeground(42,n);}catch(RuntimeException e){MarketStore.running=false;MarketStore.status="Background monitor unavailable · foreground prices active";android.util.Log.w("RoughPath","Foreground registration rejected",e);stopSelf();return;}MarketStore.running=true;wake=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"RoughPath:Prices");try{wake.acquire();}catch(SecurityException e){android.util.Log.w("RoughPath","Wake lock unavailable",e);}jobs.scheduleWithFixedDelay(()->{if(stopped)return;try{long now=System.currentTimeMillis();if(socket==null||socket.isClosed()||(now-lastFrame>20000&&now-lastConnect>20000)){connect();}}catch(Exception e){MarketStore.status="Reconnecting";}},0,3,TimeUnit.SECONDS);jobs.scheduleWithFixedDelay(this::history,0,60,TimeUnit.SECONDS);}
 private synchronized void connect(){if(stopped)return;lastConnect=System.currentTimeMillis();if(socket!=null)socket.close();MarketStore.status="Connecting";try{socket=new WebSocketClient(new URI("wss://backend-pricing.eu.gains.trade/v4")){public void onOpen(ServerHandshake h){if(PriceMonitorService.this.socket!=this||stopped)return;lastFrame=System.currentTimeMillis();MarketStore.status="Connected · background active";jobs.execute(()->history());}public void onMessage(String raw){if(PriceMonitorService.this.socket!=this||stopped)return;lastFrame=System.currentTimeMillis();PriceFeed.ingest(raw,lastFrame);}public void onClose(int code,String reason,boolean remote){if(PriceMonitorService.this.socket!=this||stopped)return;MarketStore.status="Disconnected · retrying";}public void onError(Exception ex){if(PriceMonitorService.this.socket!=this||stopped)return;MarketStore.status="Price socket error · "+ex.getClass().getSimpleName()+" · retrying";}};socket.setConnectionLostTimeout(15);socket.connect();}catch(Exception e){MarketStore.status="Connection failed · retrying";}}
 private JSONObject getJson(String url)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(15000);try{if(c.getResponseCode()!=200)throw new IOException("HTTP "+c.getResponseCode());ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)bytes.write(b,0,n);}return new JSONObject(bytes.toString("UTF-8"));}finally{c.disconnect();}}
 private void history(){synchronized(this){if(historyBusy||stopped)return;historyBusy=true;}boolean ok=false;try{
  try{JSONObject r=getJson("https://backend-pricing.eu.gains.trade/charts");JSONArray os=r.getJSONArray("opens"),hs=r.getJSONArray("highs"),ls=r.getJSONArray("lows"),cs=r.getJSONArray("closes");for(int i=0;i<Math.min(Math.min(os.length(),hs.length()),Math.min(ls.length(),cs.length()))&&i<=1000;i++){if(os.isNull(i)||hs.isNull(i)||ls.isNull(i)||cs.isNull(i))continue;MarketStore.seedOhlc(i,os.getDouble(i),hs.getDouble(i),ls.getDouble(i),cs.getDouble(i),r.optLong("time",System.currentTimeMillis()));ok=true;}}catch(Exception ignored){}
  int[] pairs={0,1,300,313};String[] symbols={"BTC-USD","ETH-USD","BTCDEGEN-USD","ETHDEGEN-USD"};
  for(int i=0;i<pairs.length&&!stopped;i++){for(String chain:new String[]{"polygon","arbitrum"}){try{long to=System.currentTimeMillis(),from=to-300*60000L;JSONArray rows=getJson("https://api.gains.trade/v1/"+chain+"/markets/"+symbols[i]+"/candles?interval=1m&from="+from+"&to="+to).getJSONArray("data"),a=new JSONArray();for(int k=0;k<rows.length();k++){JSONObject r=rows.getJSONObject(k);double o=r.getDouble("open"),h=r.getDouble("high"),l=r.getDouble("low"),close=r.getDouble("close");long t=r.getLong("time");if(t>=1000000000L&&t<1000000000000L)t*=1000;t=t/60000*60000;if(t>0&&t<=to&&Double.isFinite(o)&&Double.isFinite(h)&&Double.isFinite(l)&&Double.isFinite(close)&&l>0&&h>=Math.max(o,close)&&l<=Math.min(o,close))a.put(new JSONObject().put("t",t).put("o",o).put("h",h).put("l",l).put("c",close).put("source","gains-history"));}MarketStore.merge(pairs[i],a);MarketStore.save(true);ok=true;break;}catch(Exception ignored){}}}
  MarketStore.historyStatus=ok?"Gains history + live · 1m":"History unavailable · cached/live candles shown";
 }finally{historyBusy=false;/* The fixed-delay job already retries every minute; never fork retry chains. */}}
 public int onStartCommand(Intent i,int flags,int id){if(i!=null&&"STOP".equals(i.getAction())){getSharedPreferences("market",0).edit().putBoolean("keepAlive",false).apply();stopSelf();return START_NOT_STICKY;}if(i!=null&&"RECONNECT".equals(i.getAction()))try{jobs.execute(()->{if(System.currentTimeMillis()-lastConnect>1000||socket==null||socket.isClosed())connect();});}catch(RejectedExecutionException ignored){}return START_STICKY;}
 public IBinder onBind(Intent i){return null;}
 public void onDestroy(){stopped=true;MarketStore.running=false;MarketStore.status="Monitoring stopped";if(socket!=null)socket.close();jobs.shutdownNow();MarketStore.save(true);if(wake!=null&&wake.isHeld())wake.release();super.onDestroy();}
}
